-- 2026-08 quality repair: the mock officially supports the generic `score`
-- metric.  Use it for pain/RPE/data-quality observations instead of abusing
-- `blood_pressure`, and keep the compact value_text human-readable.
UPDATE metrics
SET type = 'score',
    value = 1 + ((CAST(substr(metric_id, -4) AS INTEGER) - 1) % 3),
    value_text = printf('右膝%d/10；RPE%d/10；同步正常',
                        1 + ((CAST(substr(metric_id, -4) AS INTEGER) - 1) % 3),
                        3 + ((CAST(substr(metric_id, -4) AS INTEGER) - 1) % 4)),
    unit = 'score'
WHERE metric_id LIKE 'metric_knee_%';

