-- Initial health history must stop at the S00 kickoff.  Background readings
-- recorded after 2026-07-06 09:10 are moved back sixty days; the explicit
-- July 6 baseline is restored below.
UPDATE metrics
SET recorded_at = strftime('%Y-%m-%dT%H:%M:%S+08:00', recorded_at, '-60 days')
WHERE recorded_at > '2026-07-06T09:10:00+08:00';
UPDATE workouts
SET started_at = strftime('%Y-%m-%dT%H:%M:%S+08:00', started_at, '-60 days')
WHERE started_at > '2026-07-06T09:10:00+08:00';

