SET recorded_at='2026-07-06T08:11:00+08:00'
WHERE metric_id='health_baseline_sleep_0706';
UPDATE metrics
SET recorded_at='2026-07-06T08:19:00+08:00'
WHERE metric_id='health_baseline_hr_0706';
UPDATE metrics
SET metric_id='health_baseline_knee_0706', type='score', value=2,
    value_text='右膝2/10；平路走跑后偶发酸胀', unit='score', recorded_at='2026-07-06T08:25:00+08:00'
WHERE metric_id='metric_knee_0067';

-- 2026-08 second-pass manual-cat repair: historical knee/RPE observations are
-- irregular real-world measurements rather than a short repeated digit cycle.
UPDATE metrics
SET value = CASE (rowid % 17)
  WHEN 0 THEN 1 WHEN 1 THEN 2 WHEN 2 THEN 1 WHEN 3 THEN 3 WHEN 4 THEN 2
  WHEN 5 THEN 2 WHEN 6 THEN 1 WHEN 7 THEN 3 WHEN 8 THEN 1 WHEN 9 THEN 2
  WHEN 10 THEN 3 WHEN 11 THEN 2 WHEN 12 THEN 1 WHEN 13 THEN 1
  WHEN 14 THEN 2 WHEN 15 THEN 3 ELSE 2 END
WHERE metric_id LIKE 'metric_knee_%';

UPDATE metrics
SET value_text = '右膝' || CAST(value AS INTEGER) || '/10；RPE' ||
  CASE (rowid % 19)
    WHEN 0 THEN 3 WHEN 1 THEN 5 WHEN 2 THEN 4 WHEN 3 THEN 3 WHEN 4 THEN 6
    WHEN 5 THEN 4 WHEN 6 THEN 5 WHEN 7 THEN 3 WHEN 8 THEN 4 WHEN 9 THEN 6
    WHEN 10 THEN 3 WHEN 11 THEN 5 WHEN 12 THEN 4 WHEN 13 THEN 4
    WHEN 14 THEN 3 WHEN 15 THEN 6 WHEN 16 THEN 5 WHEN 17 THEN 3 ELSE 4 END
  || '/10；' || CASE (rowid % 7)
    WHEN 0 THEN '晨间步行后，同步正常'
    WHEN 1 THEN '通勤骑行后，同步正常'
    WHEN 2 THEN '楼梯活动后，同步正常'
    WHEN 3 THEN '轻松游泳后，同步正常'
    WHEN 4 THEN '休息日晨测，同步正常'
    WHEN 5 THEN '走跑交替后，同步正常'
    ELSE '晚间拉伸后，同步正常' END
WHERE metric_id LIKE 'metric_knee_%';

-- 2026-08 third-pass clone repair: each historical score records a concrete
-- activity context and uses several normal note layouts.
UPDATE metrics SET value_text = CASE ((rowid / 4) % 40)
  WHEN 0 THEN '晨起：平地步行十分钟；无新增不适'
  WHEN 1 THEN '通勤骑行二十分钟（低阻力），膝部稳定'
  WHEN 2 THEN '连续下两层楼时，出现轻微酸感'
  WHEN 3 THEN '浅水区/轻松游泳结束后：状态平稳'
  WHEN 4 THEN '完整休息日——晚间自评'
  WHEN 5 THEN '走跑交替结束十五分钟后；记录一次'
  WHEN 6 THEN '髋踝拉伸完成后（晨间观察）'
  WHEN 7 THEN '办公久坐，起身时略有僵硬'
  WHEN 8 THEN '平路快走后：没有肿胀、没有发热'
  WHEN 9 THEN '低阻力室内车结束；主观感受平稳'
  WHEN 10 THEN '雨天居家活动后，自评一次'
  WHEN 11 THEN '午间散步→返回办公室后的记录'
  WHEN 12 THEN '泡沫轴放松后，活动度有改善'
  WHEN 13 THEN '下坡步行比平路更敏感；扶栏完成'
  WHEN 14 THEN '换项练习：只做鞋袜流程'
  WHEN 15 THEN '周末采购步行后｜晚间记录'
  WHEN 16 THEN '泳池蹬壁次数减少后，更舒服'
  WHEN 17 THEN '自行车坐垫下调一档——观察一次'
  WHEN 18 THEN '热身充分时：前十分钟稳定'
  WHEN 19 THEN '睡眠不足次日（保守记录）'
  WHEN 20 THEN '早晨上下公交台阶后；记录感受'
  WHEN 21 THEN '晚饭后，社区慢走一圈：无变化'
  WHEN 22 THEN '短距离提频练习后——复核'
  WHEN 23 THEN '未训练日；仅有家务活动'
  WHEN 24 THEN '雨后路面湿滑，改为室内步行（完成）'
  WHEN 25 THEN '游泳技术课结束：观察一次'
  WHEN 26 THEN '通勤站立四十分钟后/记录'
  WHEN 27 THEN '骑行中保持高踏频、低阻力；膝部稳定'
  WHEN 28 THEN '慢跑五分钟后，主动改为步行→不适未升高'
  WHEN 29 THEN '周中恢复日：晨间自评、晚间复核'
  WHEN 30 THEN '下楼时使用扶手（两层）；感受轻微'
  WHEN 31 THEN '长时间会议结束，起身略僵；走动后缓解'
  WHEN 32 THEN '室内拉伸二十分钟后：活动度改善'
  WHEN 33 THEN '周末公园平路散步——记录'
  WHEN 34 THEN '跳跃/冲刺：均未进行'
  WHEN 35 THEN '更换缓震鞋垫后，第一次步行（短时）'
  WHEN 36 THEN '骑行后先放松，再记录疼痛；顺序固定'
  WHEN 37 THEN '浅水行走练习结束｜自评'
  WHEN 38 THEN '连续两天降载后：恢复观察（早/晚）'
  WHEN 39 THEN '饮水正常、进食正常；晚间记录'
  ELSE '日常活动后的状态记录' END
WHERE metric_id LIKE 'metric_knee_%';

UPDATE metrics
SET value_text = CASE (rowid % 5)
  WHEN 0 THEN '右膝' || CAST(value AS INTEGER) || '/10，RPE' || CASE (rowid % 19) WHEN 0 THEN 3 WHEN 1 THEN 5 WHEN 2 THEN 4 WHEN 3 THEN 3 WHEN 4 THEN 6 WHEN 5 THEN 4 WHEN 6 THEN 5 WHEN 7 THEN 3 WHEN 8 THEN 4 WHEN 9 THEN 6 WHEN 10 THEN 3 WHEN 11 THEN 5 WHEN 12 THEN 4 WHEN 13 THEN 4 WHEN 14 THEN 3 WHEN 15 THEN 6 WHEN 16 THEN 5 WHEN 17 THEN 3 ELSE 4 END || '/10；' || value_text
  WHEN 1 THEN value_text || '；右膝' || CAST(value AS INTEGER) || '/10，主观强度' || CASE (rowid % 19) WHEN 0 THEN 3 WHEN 1 THEN 5 WHEN 2 THEN 4 WHEN 3 THEN 3 WHEN 4 THEN 6 WHEN 5 THEN 4 WHEN 6 THEN 5 WHEN 7 THEN 3 WHEN 8 THEN 4 WHEN 9 THEN 6 WHEN 10 THEN 3 WHEN 11 THEN 5 WHEN 12 THEN 4 WHEN 13 THEN 4 WHEN 14 THEN 3 WHEN 15 THEN 6 WHEN 16 THEN 5 WHEN 17 THEN 3 ELSE 4 END || '/10'
  WHEN 2 THEN '晨间记录：' || value_text || '。右膝' || CAST(value AS INTEGER) || '/10，RPE' || CASE (rowid % 19) WHEN 0 THEN 3 WHEN 1 THEN 5 WHEN 2 THEN 4 WHEN 3 THEN 3 WHEN 4 THEN 6 WHEN 5 THEN 4 WHEN 6 THEN 5 WHEN 7 THEN 3 WHEN 8 THEN 4 WHEN 9 THEN 6 WHEN 10 THEN 3 WHEN 11 THEN 5 WHEN 12 THEN 4 WHEN 13 THEN 4 WHEN 14 THEN 3 WHEN 15 THEN 6 WHEN 16 THEN 5 WHEN 17 THEN 3 ELSE 4 END || '/10'
  WHEN 3 THEN '活动后复盘（' || value_text || '）：右膝' || CAST(value AS INTEGER) || '/10；RPE' || CASE (rowid % 19) WHEN 0 THEN 3 WHEN 1 THEN 5 WHEN 2 THEN 4 WHEN 3 THEN 3 WHEN 4 THEN 6 WHEN 5 THEN 4 WHEN 6 THEN 5 WHEN 7 THEN 3 WHEN 8 THEN 4 WHEN 9 THEN 6 WHEN 10 THEN 3 WHEN 11 THEN 5 WHEN 12 THEN 4 WHEN 13 THEN 4 WHEN 14 THEN 3 WHEN 15 THEN 6 WHEN 16 THEN 5 WHEN 17 THEN 3 ELSE 4 END || '/10'
  ELSE value_text || '。疼痛记录为右膝' || CAST(value AS INTEGER) || '/10，RPE' || CASE (rowid % 19) WHEN 0 THEN 3 WHEN 1 THEN 5 WHEN 2 THEN 4 WHEN 3 THEN 3 WHEN 4 THEN 6 WHEN 5 THEN 4 WHEN 6 THEN 5 WHEN 7 THEN 3 WHEN 8 THEN 4 WHEN 9 THEN 6 WHEN 10 THEN 3 WHEN 11 THEN 5 WHEN 12 THEN 4 WHEN 13 THEN 4 WHEN 14 THEN 3 WHEN 15 THEN 6 WHEN 16 THEN 5 WHEN 17 THEN 3 ELSE 4 END || '/10' END
WHERE metric_id LIKE 'metric_knee_%';
